#include <iiMultimodalAgent/mcp/HttpClient.h>
#include <iiMultimodalAgent/agent/McpTools.h>

iiMultimodalAgent::mcp::HttpOptions http;
http.endpoint = QUrl("https://app.example/mcp"); // 호스트가 선택한 실제 앱 endpoint
http.bearerToken = [credentials] { return credentials->currentAccessToken(); };
auto client = std::make_shared<iiMultimodalAgent::mcp::HttpClient>(http);
auto tools = iiMultimodalAgent::agent::mcpTools(client, {"society", "com.iisacc.society"});
for (auto& tool : tools) registry->add(std::move(tool));
